// Récupère la vidéo déposée et la place dans « data ».
const src = $('Déposer une vidéo').first();
const fichier = Object.values(src.binary ?? {})[0];
if (!fichier) throw new Error('Aucun fichier reçu : déposez une vidéo ou un fichier audio.');
return [{ json: { nom_fichier: fichier.fileName, contexte: src.json.contexte ?? '', public: src.json.public ?? '' }, binary: { data: fichier } }];

// Sous-titres SRT et VTT à partir des segments horodatés, et transcription repérée pour l'IA.
const t = $input.first().json;
const segs = t.segments ?? [];
if (!segs.length) throw new Error('Transcription vide : la vidéo contient-elle de la parole ?');
const hms = (s, sep) => { const ms = Math.round(s * 1000); const h = Math.floor(ms / 3600000), m = Math.floor(ms / 60000) % 60, sec = Math.floor(ms / 1000) % 60;
  return [h, m, sec].map(n => String(n).padStart(2, '0')).join(':') + sep + String(ms % 1000).padStart(3, '0'); };
const mmss = s => { const m = Math.floor(s / 60), sec = Math.floor(s % 60); return String(m).padStart(2, '0') + ':' + String(sec).padStart(2, '0'); };
const srt = segs.map((s, i) => `${i + 1}\n${hms(s.start, ',')} --> ${hms(s.end, ',')}\n${s.text.trim()}\n`).join('\n');
const vtt = 'WEBVTT\n\n' + segs.map(s => `${hms(s.start, '.')} --> ${hms(s.end, '.')}\n${s.text.trim()}\n`).join('\n');
const reperee = segs.map(s => `[${mmss(s.start)}] ${s.text.trim()}`).join('\n');
const duree = segs[segs.length - 1].end;
const mots = t.text.split(/\s+/).filter(Boolean).length;
return [{ json: { texte: t.text, reperee, srt, vtt, duree_s: Math.round(duree), duree: mmss(duree), mots, segments: segs.length, temps_transcription_s: t.temps_de_calcul_s ?? null } }];

