// Contrôles automatiques puis assemblage du pack (fichiers joints + récapitulatif).
const st = $('Sous-titres et repères').first().json;
const a = $('Analyse de la vidéo').first().json.output;
const r = $('Rédaction de la campagne').first().json.output;
const src = $('Préparer le fichier').first().json;
const sec = s => { const m = /^(\d{1,2}):(\d{2})$/.exec(String(s).trim()); return m ? +m[1] * 60 + +m[2] : NaN; };
const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const transcription = norm(st.texte);
const ch = a.chapitres ?? [];
const nbMots = s => String(s).split(/\s+/).filter(Boolean).length;
const controles = [
  { label: 'Chapitres : premier à 00:00', ok: ch.length > 0 && sec(ch[0].debut) === 0 },
  { label: 'Chapitres : ordre chronologique et dans la durée', ok: ch.every((c, i) => !isNaN(sec(c.debut)) && sec(c.debut) <= st.duree_s && (i === 0 || sec(c.debut) > sec(ch[i - 1].debut))) },
  { label: 'Chapitres : 3 au minimum (exigence YouTube)', ok: ch.length >= 3 },
  { label: 'Citations reprises mot pour mot', ok: (a.citations ?? []).length > 0 && a.citations.every(c => transcription.includes(norm(c.texte))) },
  { label: 'Article : 400 à 600 mots', ok: nbMots(r.article_markdown) >= 380 && nbMots(r.article_markdown) <= 650, detail: nbMots(r.article_markdown) + ' mots' },
  { label: 'Meta description : 150 caractères au plus', ok: r.meta_description.length <= 155, detail: r.meta_description.length + ' car.' },
  { label: '3 posts LinkedIn', ok: (r.posts_linkedin ?? []).length === 3 },
  { label: 'Post court : 300 caractères au plus', ok: r.post_court.length <= 300, detail: r.post_court.length + ' car.' },
];
const aRevoir = controles.filter(c => !c.ok).map(c => c.label);
const chapitresYT = ch.map(c => c.debut + ' ' + c.titre).join('\n');
const campagne = [
  '# Campagne de contenus · ' + a.titre_video, '',
  '*Source : ' + src.nom_fichier + ' · ' + st.duree + ' · ' + st.mots + ' mots transcrits*', '',
  '## Vidéo', '', '**Titre :** ' + a.titre_video, '', '**Résumé :** ' + a.resume, '', '**Chapitres (description YouTube) :**', '', '```', chapitresYT, '```', '',
  '**Mots-clés :** ' + a.mots_cles.join(', '), '',
  '## Citations', '', ...a.citations.map(c => '- « ' + c.texte + ' » (' + c.horodatage + ')'), '',
  '## LinkedIn', '', ...r.posts_linkedin.flatMap((p, i) => ['### Post ' + (i + 1), '', p, '']),
  '## Instagram / Facebook', '', r.post_court, '',
  '## Newsletter', '', '**Objet :** ' + r.newsletter_objet, '', r.newsletter_texte, '',
  '## Article de blog', '', '**Meta description :** ' + r.meta_description, '', r.article_markdown, '',
].join('\n');
const fichier = async (txt, nom, type) => await this.helpers.prepareBinaryData(Buffer.from(txt, 'utf8'), nom, type);
const base = (src.nom_fichier || 'video').replace(/\.[^.]+$/, '');
return [{ json: { titre: a.titre_video, resume: a.resume, duree: st.duree, mots: st.mots, temps_transcription_s: st.temps_transcription_s,
    chapitres: ch, citations: a.citations, mots_cles: a.mots_cles, posts_linkedin: r.posts_linkedin, post_court: r.post_court,
    newsletter_objet: r.newsletter_objet, article_titre: r.article_titre, controles, a_revoir: aRevoir.join(' · ') },
  binary: {
    sous_titres_srt: await fichier(st.srt, base + '.srt', 'application/x-subrip'),
    sous_titres_vtt: await fichier(st.vtt, base + '.vtt', 'text/vtt'),
    article: await fichier(r.article_markdown, 'article-blog.md', 'text/markdown'),
    campagne: await fichier(campagne, 'campagne-complete.md', 'text/markdown'),
  } }];
